package com.sxpcwlkj.system.service.impl;

import cn.hutool.captcha.CaptchaUtil;
import cn.hutool.captcha.CircleCaptcha;
import cn.hutool.captcha.LineCaptcha;
import cn.hutool.captcha.ShearCaptcha;
import cn.hutool.core.convert.Convert;
import com.sxpcwlkj.common.code.entity.CaptchaEntity;
import com.sxpcwlkj.common.code.entity.ConfigEntity;
import com.sxpcwlkj.common.constant.Constants;
import com.sxpcwlkj.common.enums.ConfigKeyNum;
import com.sxpcwlkj.common.enums.SystemCommonEnum;
import com.sxpcwlkj.common.properties.CaptchaProperties;
import com.sxpcwlkj.common.utils.DataUtil;
import com.sxpcwlkj.redis.RedisUtil;
import com.sxpcwlkj.system.service.CaptchaService;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.apache.commons.lang3.StringUtils;
import org.springframework.stereotype.Service;

import java.time.Duration;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.concurrent.atomic.AtomicBoolean;

@Slf4j
@RequiredArgsConstructor
@Service("captcha")
public class CaptchaServiceImpl implements CaptchaService {

    private final CaptchaProperties captchaProperties;


    @Override
    public Map<String, Object> getCaptcha(Integer type, String code) {

        Map<String, Object> data = new HashMap<>(16);
        // msg：验证码未开启
        List<ConfigEntity> convert = RedisUtil.getCacheList(ConfigKeyNum.config_base.getKey());
        AtomicBoolean isOpen= new AtomicBoolean(false);

        if(convert.isEmpty()){
            return data;
        }
        convert.forEach(smsConfigEntity -> {
            if("sys_base_captcha_state".equals(smsConfigEntity.getConfigKey())){
               if(Objects.equals(Convert.toInt(smsConfigEntity.getConfigValue()), SystemCommonEnum.SYS_COMMON_STATE_OPEN.getValue())){
                   isOpen.set(true);
               }
            }
        });
        if (!isOpen.get()) {
            data.put(CaptchaEntity.CODE.CAPTCHA_MSG.getValue(), "系统验证码未开启!");
            return data;
        }
        // 验证码为空
        if (StringUtils.isEmpty(code)) {
            data.put(CaptchaEntity.CODE.CAPTCHA_MSG.getValue(), "缺少验证[code]参数");
            return data;
        }

        // 初始化参数
        String bas64 = "";
        data.put(CaptchaEntity.CODE.CAPTCHA.getValue(), bas64);
        data.put(CaptchaEntity.CODE.CAPTCHA_VALUE.getValue(), null);
        data.put(CaptchaEntity.CODE.TYPE.getValue(), type);
        data.put(CaptchaEntity.CODE.UUID.getValue(), DataUtil.getRandomUUID());
        data.put(CaptchaEntity.CODE.CAPTCHA_KEY.getValue(), code);


        //初始化验证码背景
        if (!"000000".equals(code)) {

            switch (captchaProperties.getType()) {
                case "LINE":
                    //定义图形验证码的长和宽
                    LineCaptcha lineCaptcha = CaptchaUtil.createLineCaptcha(280, 100);
                    data.put(CaptchaEntity.CODE.CAPTCHA.getValue(), lineCaptcha.getImageBase64());
                    data.put(CaptchaEntity.CODE.CAPTCHA_VALUE.getValue(), lineCaptcha.getCode());
                    log.info("验证码：线段干扰");
                    break;
                case "CIRCLE":
                    //定义图形验证码的长、宽、验证码字符数、干扰元素个数
                    CircleCaptcha circleCaptcha = CaptchaUtil.createCircleCaptcha(280, 100, 4, 20);
                    data.put(CaptchaEntity.CODE.CAPTCHA.getValue(), circleCaptcha.getImageBase64());
                    data.put(CaptchaEntity.CODE.CAPTCHA_VALUE.getValue(), circleCaptcha.getCode());
                    log.info("验证码：圆圈干扰");
                    break;
                case "SHEAR":
                    //定义图形验证码的长、宽、验证码字符数、干扰线宽度
                    ShearCaptcha shearCaptcha = CaptchaUtil.createShearCaptcha(280, 100, 4, 4);
                    data.put(CaptchaEntity.CODE.CAPTCHA.getValue(), shearCaptcha.getImageBase64());
                    data.put(CaptchaEntity.CODE.CAPTCHA_VALUE.getValue(), shearCaptcha.getCode());
                    log.info("验证码：扭曲干扰");
                    break;
                case "CALCULATE":
                    log.info("验证码：计算题型");
                    break;
                default:
                    log.info("验证码：未匹配！");
                    break;
            }
        }

        RedisUtil.setCacheObject(DataUtil.getString(data.get(CaptchaEntity.CODE.UUID.getValue())), data, Duration.ofMinutes(Constants.CAPTCHA_EXPIRATION));
        data.remove(CaptchaEntity.CODE.TYPE.getValue());
        data.remove(CaptchaEntity.CODE.CAPTCHA_VALUE.getValue());
        data.remove(CaptchaEntity.CODE.CAPTCHA_KEY.getValue());
        //只返回 验证码和uuid
        return data;
    }


}
